const crypto = require('crypto');

// AES加密
function encrypt(src, key, iv) {
  if (!src || !key) return null;
  let cipher = crypto.createCipheriv('aes-128-cbc', Buffer.from(key), iv);
  cipher.setAutoPadding(true);
  let result = cipher.update(src, 'utf8', 'base64');
  result += cipher.final('base64');
  return result;
}

// AES解密
function decrypt (encrypted, key, iv) {
  if (!encrypted || !key) return null;
  let decipher = crypto.createDecipheriv('aes-128-cbc', Buffer.from(key, 'utf8'), iv);
  decipher.setAutoPadding(true);
  let result = decipher.update(Buffer.from(encrypted, 'base64'), 'base64', 'utf8');
  result += decipher.final('utf8');
  return result;
}

const src = '111111';
const key = 'k.www.10jqka.com';
const iv = 'offset.10jqkacom';
const encrypted = encrypt(src, key, iv);
console.log('encrypted', encrypted);
const decrypted = decrypt(encrypted, key, iv);
console.log('decrypted', decrypted);
console.log(decrypted === src);
